"""Figures and report from saved evidence; no simulation, selection or fitting."""
import gzip,json,math,sys
from pathlib import Path
from analyze150 import D,R,read,charged
def f(x,n=3):return 'N/D' if x is None else f'{x:.{n}f}'
def table(headers,rows):return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+''.join('| '+' | '.join(map(str,r))+' |\n' for r in rows)+'\n'
def main():
 with charged('saved-figures-and-report'+(('-'+sys.argv[1]) if len(sys.argv)>1 else '')):
  import matplotlib;matplotlib.use('Agg')
  import matplotlib.pyplot as plt
  a=read(D/'analysis.json');runs={x['name']:x for x in a['full_runs']};cs=a['corners'];figdir=D/'figures';figdir.mkdir(exist_ok=True)
  plt.rcParams.update({'font.size':10,'axes.grid':True,'grid.alpha':.25,'figure.dpi':145})
  def export(fig,name):
   fig.tight_layout();fig.savefig(figdir/(name+'.png'));fig.savefig(figdir/(name+'.svg'));p=figdir/(name+'.svg');p.write_text('\n'.join(x.rstrip() for x in p.read_text(encoding='utf-8').splitlines())+'\n',encoding='utf-8',newline='\n');plt.close(fig)
  def load(name):return read(R/runs[name]['source'])['Riders'][0]['Samples']
  fig,axes=plt.subplots(2,1,figsize=(10,7),sharex=True)
  for case,label in [('B-predicted-shift-fixed','Same tape / predicted1s'),('C-observed-shift-fixed','Same tape / observed1s'),('D-fresh-K1','Observed1s / fresh K1')]:
   t=read(D/'diagnosis-safe'/('A-'+case+'.json.gz'));axes[0].plot([p['Time'] for p in t['Points']],[p['Rider']['SlideRadians']*180/math.pi for p in t['Points']],label=label)
   x=next(x for x in a['diagnosis'] if x['model']=='A' and x['name']==case);axes[1].semilogy([p[0] for p in x['errors']],[max(p[1],1e-8) for p in x['errors']],label=label)
  axes[0].axhline(45,c='k',ls='--',label='Unchanged beta envelope');axes[0].set(ylabel='beta [deg]',title='Causal separation: fixed commands already lose forecast legality');axes[1].set(xlabel='Absolute time [s]',ylabel='Position difference [m]');axes[0].legend(fontsize=8);export(fig,'causal-tape')
  fig,axes=plt.subplots(1,2,figsize=(11,5))
  for name,label in [('fixed-certified-tape-native-A','A fixed tape: crossing13.47s'),('robust150-exact-recovery-A','A feedback: rolling finish16.463s'),('robust150-exact-recovery-B','B feedback: rolling finish16.471s')]:
   ss=load(name);axes[0].plot([s['Input']['Rider']['Position']['X'] for s in ss],[s['Input']['Rider']['Position']['Y'] for s in ss],label=label);axes[1].plot([s['Input']['Time'] for s in ss],[s['Input']['Rider']['Speed']*3.6 for s in ss],label=label)
  geometry=read(R/'docs/experiments/causal-yaw-throttle/progressive-b-viewer-geometry.json')
  for edge in ['inner','outer']:
   pp=[p[edge] for s in geometry['segments'] for p in s['sections']];axes[0].plot([p['x'] for p in pp],[p['y'] for p in pp],c='gray',lw=.8)
  axes[0].set(aspect='equal',xlabel='x [m]',ylabel='y [m]',title='90km/h diagnostic; reference23m to318.779m');axes[1].set(xlabel='Absolute time [s]',ylabel='Speed [km/h]',title='Native continuous Box2D');axes[1].legend(fontsize=7);export(fig,'native-recovery')
  fig,axes=plt.subplots(2,2,figsize=(11,7),sharex=True)
  for name,label in [('baseline149-final148','A baseline149'),('separated149-autonomous','B baseline149'),('robust150-prefix-B-45','B planner150 after native45.8s prefix')]:
   ss=[s for s in load(name) if 2*318.77874994277954+194.38937497<=s['Input']['Rider']['TotalReferenceMeters']<=3*318.77874994277954];ref=[s['Input']['Rider']['TotalReferenceMeters']-2*318.77874994277954 for s in ss]
   for ax,values in zip(axes.flat,[[s['Input']['Rider']['Speed']*3.6 for s in ss],[s['Input']['Rider']['Road']['OffsetMeters'] for s in ss],[s['Input']['Active']['Drive'] for s in ss],[s['Input']['Rider']['SlideRadians']*180/math.pi for s in ss]]):ax.plot(ref,values,label=label)
  for ax,title in zip(axes.flat,['Speed [km/h]','Actual offset [m]','Active throttle [0..1]','beta [deg]']):ax.set(ylabel=title,xlabel='Lap reference [m]')
  axes[0,0].set_title('B last bend + following straight (diagnostic prefix)');axes[0,1].legend(fontsize=7);export(fig,'last-corner')
  fig,axes=plt.subplots(1,2,figsize=(11,4.5));labels=[];cpus=[]
  for name,x in a['plan_audits'].items():
   axes[0].plot([r['time_s'] for r in x['rows']],[readrow['Review']['CpuSeconds'] for readrow in journal(name)],'.-',label=name.replace('robust150-',''),ms=3)
   labels.append(name.replace('robust150-',''));cpus.append(runs[name]['controller_cpu_s'])
  axes[0].set(xlabel='Native time [s]',ylabel='Successful decision CPU [s]',title='Abstention cost included in totals, not successful trace');axes[0].legend(fontsize=6);axes[1].barh(labels,cpus);axes[1].set(xlabel='Attempted controller CPU [s]',title='Different scopes; no full-race speedup claim');export(fig,'cpu')
  text='# Badanie #150 — Robust Autonomous Racing Planner\n\n**PARTIAL.** Odzyskano dokładny przypadek odmowy po1,0s na obu modelach, lecz nowy sterownik nie ukończył trzech okrążeń ze startu. Pełna próba A odmówiła po0,4s; pełnej próby B nie uruchomiono po niepowodzeniu bramek. Wszystkie nowe algorytmy pozostają OFF. Baza: PR148, `8aedd292bda2de5742952f4ddc280f873f5a517c`; Draft PR149, bez merge.\n\n'
  text+='## 1. Przyczyna odmowy starego planera\n\nRozdzielono fizykę A i B od nazw kontrfaktycznych A–E. Oryginalny pełny plan z0,8s odtworzono punkt po punkcie. Przesunięcie tego samego planu do jego **przewidywanego** stanu1,0s pozostaje legalne. Przesunięcie do **rzeczywiście zaobserwowanego** stanu1,0s z identycznymi przyszłymi komendami traci legalność. Kolejka jest identyczna. W tym przypadku nowy ogon K1 nie jest przyczyną: nie zmieniła się ani jedna komenda przed utratą legalności.\n\n'
  ds=[x for x in a['diagnosis'] if x['name'] in ['A-original-fixed','B-predicted-shift-fixed','C-observed-shift-fixed','D-fresh-K1','D-observed-shift-append-K1','E-heading-1','E-heading--1','E-wheel-1','E-crank-1']]
  text+=table(['Model','Kontrfaktyczny plan','Legalny','Pierwsza inna komenda s','Pierwszy odrzucony punkt s','β max °','Powód'],[[x['model'],x['name'],x['legal'],f(x['first_different_action_time']),f(x['first_rejected_point_time']),f(x['beta']),x['reason']] for x in ds])
  text+='Dla identycznej taśmy błąd XY przekracza1mm po3,11s, a β przekracza45° po10,93s. Zmiana samego headingu o wcześniej zmierzony błąd daje odrzucenie po10,87s, znak przeciwny narusza rezerwę obrysu po9,36s. Same wheel/crank pozostają legalne. Skutki pozycji/prędkości zależą od znaku i modelu: pełne rozbicie E zapisano w `diagnosis-safe/` i `analysis.json`. Nie jest to dowód chaosu rzeczywistego motocykla. To dowód wrażliwości długiej otwartej prognozy na wektor błędu obserwacja–predyktor oraz dyskretną integrację. Różnica7,9µm sama nie wystarcza do przypisania winy fizyce.\n\nŚwieżo regenerowany K1 zmienia komendę dopiero po5,8s (krok24 po1s): skręt0,5° zamiast0°, ten sam gaz częściowy. To osobna gałąź dyskretna. Dopisanie K1 za pełną taśmą nic nie zmienia, ponieważ odrzucenie występuje przed końcem taśmy. Natywne wykonanie stałej taśmy, bez regenerowania K1, przekracza obrys po13,47s(A)/13,48s(B), przy β≈30,24°. Różne momenty i mechanizmy odrzucenia prognozy oraz natywnego świata potwierdzają ograniczenie długiego certyfikatu modelowego. Natywny przebieg zachowuje pełny prefiks i kolejkę. Pierwszą przerwaną próbę diagnostyczną oraz jej koszt zachowano; raw `diagnosis-summary.json` porównywał A z B indeksem z przesunięciem0,2s. W tabeli użyto poprawnego wyrównania po absolutnym czasie w `analyze150.py`.\n\n![Ta sama taśma i rozdzielenie K1](figures/causal-tape.png)\n\n'
  text+='## 2. Zaimplementowany eksperyment\n\nOgraniczone deterministyczne wyszukiwanie dwóch poziomów: maksymalnie36 pełnych kandydatów, po dwa lokalne edity, każdy do dwóch kolejnych decyzji, rozdzielone między bieżący stan, przyszłe przejścia geometrii i okolice pierwszego ryzyka. Każdy edit łączy gaz i skręt; kąty obejmują oryginalną siatkę i ogólną regułę środków sąsiednich kątów. Dopuszczono do trzech różnych pełnych planów, bez wymogu posiadania trzech, oraz próg0,02s przy zachowaniu bezpiecznego incumbenta. Tani optymistyczny dolny limit czasu korzysta z niezmienionego limitu siły i geometrii; pruningi są jawne. Nie ma losowania, CEM, premii za prędkość ani kary za szerokość.\n\nKryterium to czas do tego samego przekroju geometrycznego za łukiem; legalność obejmuje kolejny manewr. Propagacja zachowuje istniejący silnik, sprzęgło, wheel state, opony, Box2D, geometrię, limit zmiany skrętu, decyzje0,2s i prawdziwe opóźnienie0,24s. Drugi niezależny replay całego wybranego kontraktu pomija cache fizyki i lokalnych pochodnych.\n\nSprzężenie zwrotne śledzi trajektorię powstałą z własnej poprzedniej prognozy. Lokalna odpowiedź yaw jest obliczana zapytaniami niezmienionego modelu kontaktu; stała czasowa0,88s wynika z2×(0,24+0,2). To wybór konstrukcyjny, nie wyznaczona optymalna waga. Gaz bazowej polityki zachowano; przestrzeń propozycji obejmuje także edity gazu. Dwa skończone scenariusze błędu to ±skorelowany **uprzednio zmierzony** wektor1review; plik kalibracji zawiera wyłącznie delty, bez absolutnych przyszłych stanów/komend. Skala przy małej prędkości wynika z regularizacji wheel modelu. Nie stanowi to globalnie skalibrowanego przedziału odporności.\n\n'
  text+='## Tabela A — odporność i konkretne blokady\n\n'
  rows=[]
  for model in ['A','B']:
   q=read(D/f'prototype-critical-tube-midpoint-{model}.json')['Review'];x=runs['robust150-exact-recovery-'+model];rows.append([model+' / dokładny1,0s','stary: abstain1,0s','lokalny koniec '+f(x['finish_s'])+'s',str(q['Legal'])+'/'+str(q['Robust']),f(x['end_reference_m']),f(x['maximum_beta_deg']),f(x['minimum_sweep_m']),f(x['controller_cpu_s'])])
  for x in a['new_critical22']:
   q=x['Review'];best=next(y for y in q['Alternatives'] if y['Robust']);rows.append([x['Model']+' /22,6s','stary repair/retain','prognoza '+f(q['Arrival']-q['Time'])+'s',str(q['Legal'])+'/'+str(q['Robust']),f(best['EndReference']),f(best['Beta']),f(best['Sweep']),f(q['CpuSeconds'])])
  for p in a['state_probes']:
   if not p['file'].startswith('probe-midpoint-'):continue
   q=p['review'];best=sorted(q['Alternatives'],key=lambda z:(not z['Robust'],not z['Legal'],-z['EndReference']))[0];rows.append([p['file'].replace('probe-midpoint-','').replace('.json',''),'własny stan native149',p['failure'] or 'certyfikat / bez nowego świata',str(q['Legal'])+'/'+str(q['Robust']),f(best['EndReference']) if best['Robust'] else 'N/D (odrzucony)',f(best['Beta']),f(best['Sweep']),f(q['CpuSeconds'])])
  for name in ['robust150-prefix-B-28','robust150-prefix-B-45','robust150-tube-full-A']:
   x=runs[name];audit=a['plan_audits'][name];ab=audit['abstentions'];q=ab[-1]['Review'] if ab else None;rows.append([name,'natywny prefiks' if x['prefix_until'] else 'start0',x['outcome']+' / '+f(x['end_s'])+'s',str(q['Legal'])+'/'+str(q['Robust']) if q else 'ostatni: '+str(audit['rows'][-1]['forecast_legal']),f(x['end_reference_m']),f(x['maximum_beta_deg']),f(x['minimum_sweep_m']),f(x['controller_cpu_s'])])
  text+=table(['Stan','Stary / pochodzenie','Nowy wynik','Nominalne/odporne','Checkpoint ref m','β max °','Sweep m','CPU s'],rows)
  text+='Checkpoint w natywnym wierszu oznacza najdalszy rzeczywiście zaakceptowany legalny stan. W odrzuconej prognozie koniec nie jest legalnym checkpointem. Pełne początki i wszystkie odrzucenia są zapisane; tabela nie zamienia końca nielegalnej prognozy w dowód osiągalności. Wybrane plany odrzucano z powodów footprint reserve, beta45, reverse motion i braku certyfikatu sweep. Rozkład wszystkich przyczyn oraz nominalne i odporne zbiory są w `analysis.json.plan_audits`. Na0,4s istnieją trzy nominalne legalne kontynuacje, ale zero odpornych. Odrzucenie dotyczy odległego obrysu; obserwowany motocykl nadal ma4,099m zapasu. Audyt kolejnej obserwacji przesunął błędy do przewidywanego następnego stanu, zachował niezmienną kolejkę i sprawdził alternatywę retained/fresh: żaden korzeń nie pokrywa wszystkich skończonych scenariuszy. Nie dowodzi to fizycznego braku bezpiecznego sterowania poza badaną klasą polityk.\n\n'
  text+='![Rzeczywista linia i prędkość odzyskania](figures/native-recovery.png)\n\nOdzyskanie dokładnego1s wykorzystuje własny poprzedni plan0,8s jako diagnostyczną historię. Nie podano właściwego skrętu ani chwili przełączenia. Oba modele są bez kontaktów i naruszeń obrysu. Odcinek zaczyna się w ruchu90km/h przy23m i kończy na pierwszym przekroczeniu318,779m: 295,779m referencji, nie pełny bieg. Dodatkowa świeża próba rollingA ukończyła16,429048s. Nie przetestowano powtórzenia każdego nowego świata; sparowane A/B i333 dokładne replays sprawdzają kontrakty, nie zastępują powtarzalności natywnego pełnego biegu.\n\n'
  text+='## 3. Spójność, błędy prognozy i negatywne hipotezy\n\nWszystkie333 wybrane kompletne kontrakty odtworzono bez cache: pełne sekwencje komend są dokładnie identyczne i nominalnie legalne. Przy każdym wykonaniu pierwsza komenda zgadza się z wybranym kontraktem, a pending queue została porównana z natywną historią i opóźnieniem0,24s. Zmiana wartości komendy przy tym samym kontrakcie jest jawną reakcją sprzężenia na nową obserwację; nie jest porzuceniem zapowiedzianej korekty bez oceny. Należy rozróżniać identyczność przewidywanych wartości komend od tożsamości ponownie certyfikowanej polityki sprzężenia.\n\n'
  text+=table(['Próba','Decyzje','Ten sam kontrakt','Kotwice','Literalnie zgodna następna komenda','Max błąd XY kolejnej prognozy m'],[[n.replace('robust150-',''),x['reviews'],x['same_contract_reviews'],x['new_anchor_count'],str(x['followed_expected'])+'/'+str(x['expected_reviews']),f(x['maximum_error']['PositionMeters'],6)] for n,x in a['plan_audits'].items()])
  text+='Nie ukryto błędu: następne XY potrafi odbiegać około0,26m. Niezależny replay sprawdza model i kontrakt, nie zgodność dalekiej prognozy z Box2D. Dzienniki zawierają pełny stan przed decyzją, rankingi wszystkich alternatyw, pełne wybrane sekwencje, certyfikaty, prognozowane speed/β/yaw, czas do celu, faktyczne komendy/aktywacje i przyczyny zmiany. Przewidywany exit speed w widoku pochodzi z najbliższego zapisanego punktu0,1s; surowe kotwice mają pełną rozdzielczość.\n\nPo pierwszej nieudanej pełnej próbie sprawdzono odrębnie wyrównanie referencji po drodze zamiast czasu, liniaryzację na faktycznym punkcie pracy wheel, oraz wspólną lokalną inwersję yaw/slip korygującą gaz i skręt. Te kontrolowane hipotezy nie uratowały0,4s i nie poprawiły pokrycia pięciu odłożonych stanów (nadal4/5). Nie uruchomiono kolejnych pełnych prób tych wariantów. Główna blokada to mało różnorodne bezpieczne przyszłe polityki i brak potwierdzonej recourse na następnej obserwacji; limit36 i K1 jako generator ogona nadal ograniczają przestrzeń. Część pożądanego problemu projektowego pozostaje nierozwiązana.\n\n'
  text+='## Tabela B — pełny dystans i wszystkie sześć łuków\n\n'
  text+=table(['Sterownik/model','Zakres','3okr czas s','Koniec / powód','CPU sterownika s','Min sweep m'],[[x['name'],x['kind'],f(x['finish_s']) if x['kind']=='baseline149' else 'N/D',f(x['end_s'])+' / '+x['outcome'],f(x['controller_cpu_s']),f(x['minimum_sweep_m'])] for x in a['full_runs'] if x['kind'] in ['baseline149','full autonomous attempt']]+[['nowyB','nie uruchomiono','N/D','nieudane bramki','N/D','N/D']])
  selected=[x for x in cs if x['run'] in ['baseline149-final148','separated149-autonomous','robust150-tube-full-A']]
  text+=table(['Model / próba','Łuk','Czas s','V wej/min/wyj km/h','Droga m','Gaz0/cz/1 s','β° / yaw rad/s','Offset min/max m','Min wew/zew m','CPU s'],[[x['model']+(' nowy' if x['run']=='robust150-tube-full-A' else ' stary'),str(x['lap'])+'.'+str(x['bend']),f(x['seconds']),' / '.join(f(x[k],1) for k in ['entry_kph','minimum_kph','exit_kph']),f(x['path_m']),' / '.join(f(x[k]) for k in ['gas0_s','gas_partial_s','gas1_s']),f(x['beta_abs_max_deg'])+' / '+f(x['yaw_abs_max_rads']),' / '.join(f(x[k]) for k in ['offset_min_m','offset_max_m']),' / '.join(f(x[k]) for k in ['inner_min_m','outer_min_m']),f(x['decision_cpu_s'])] for x in selected])
  text+='NowyB ma N/D dla każdego z sześciu łuków; nie ma pełnego przejazdu. CPU łuku sumuje pomiary decyzji **wewnątrz łuku**, nie obejmuje wcześniejszego planowania ani całej abstencji. Źródłem odniesienia są niezmienione pomiary149, bez ponownego świata150.\n\n'
  text+=table(['Diagnostyka z natywnym prefiksem','Łuk','Czas s','Δ względem własnegoB s','V wej/min/wyj km/h','Droga m','Gaz0/cz/1 s','β° / yaw','CPU decyzji w łuku s'],[[x['run'],str(x['lap'])+'.'+str(x['bend']),f(x['seconds']),f(x['delta_model_baseline_s'],6),' / '.join(f(x[k],1) for k in ['entry_kph','minimum_kph','exit_kph']),f(x['path_m']),' / '.join(f(x[k]) for k in ['gas0_s','gas_partial_s','gas1_s']),f(x['beta_abs_max_deg'])+' / '+f(x['yaw_abs_max_rads']),f(x['decision_cpu_s'])] for x in cs if (x['run']=='robust150-prefix-B-28' and x['lap']==2 and x['bend']==2) or (x['run']=='robust150-prefix-B-45' and x['lap']==3 and x['bend']==2)])
  text+='PrefiksB45,8 kończy cały zapis po54,121619s: −0,113324s względem staregoB, ale nowy kontroler odpowiada wyłącznie za końcówkę. Łuk3.2 trwa5,868077s zamiast6,164824s (−0,296748s), droga107,602m zamiast116,844m (−9,242m), wyjście67,688 zamiast74,603km/h. Zysk w samym łuku częściowo znika na dalszym rozpędzaniu. Nie jest to poprawa pełnego autonomicznego czasu. Łuk2.2 po prefiksie28,4s pozostaje6,100897s, Δ+0,000048s.\n\n![Ostatni łuk: linia, prędkość, gaz i beta](figures/last-corner.png)\n\n'
  text+='## 4. Dlaczego B nadkłada drogi i co z ręcznym benchmarkiem\n\nDla2.2: A99,873m/B111,511m (+11,639m), B jest wolniejszy o0,495347s. Dla3.2: A100,272m/B116,844m (+16,573m), B wolniejszy o0,699258s. Większa prędkość wejścia i wyjścia B nie kompensuje dodatkowej drogi. Kryterium starego planera już porównuje czas do wspólnego geometrycznego celu: problemem nie jest jawna nagroda za szerokość.\n\nNa22,6s w A odziedziczony plan traci legalność, co uruchamia naprawę i daje beam2: skręt0°/gaz częściowy, przewidywane6,728242s do wspólnego celu. W B odziedziczony plan jest legalny, więc przeszukiwanie nie jest uruchamiane: rozważono tylko jednego kandydata, skręt0,5°/gaz0, przewidywane6,829956s. Mała różnica fizyki otwiera więc odmienne **zbiory dostępnych planów**. Nowy planner rozważa obie gałęzie niezależnie od legalności incumbenta w okresowych/geometrycznych wyszukiwaniach; na22,6s oba modele certyfikują ciąg dalszy (6,660672s/6,829910s prognozy), ale brak natywnej pełnej próby potwierdzającej te czasy.\n\nRęczna poprawaB53,784509s korzysta z natywnego prefiksu zapisanych komendA pod fizykąB. To inne wejście niż własny autonomiczny stanB28,4s. Oryginalna siatka nie zawiera1°/gaz częściowy. Ogólne środki sąsiednich kątów w150 obejmują1° z różnicą2×10⁻⁹rad wynikającą z float; nie jest to bitowo identyczna akcja. Dodanie bliskiej komendy nie reprezentuje automatycznie całej późniejszej polityki świeżegoK1 użytej w ręcznej diagnostyce. Probe150 na **dokładnie tym samym ręcznym stanie wejścia**, bez podania akcji, odmawia: brak odpornej kompletnej kontynuacji. Nie udowodniono odzyskania benchmarku przez generator ani optymalnego rankingu. To ograniczenie klasy ogona/propozycji, a nie dowód nieosiągalności.\n\n'
  text+='## 5. Koszt i profil\n\n'
  text+=table(['Próba / zakres','CPU cały eksperyment','CPU prób wyboru','p50/p95/max s','PełneK1','Fizyczne prognozy','Kontakty z inverse','Hity predykcji/requests'],[[x['name'],f(x['whole_experiment_cpu_s']),f(x['controller_cpu_s']),' / '.join(f(x[k]) for k in ['p50_cpu_s','p95_cpu_s','max_cpu_s']),x['counts']['FullK1Executions'],x['counts']['ActualForecasts'],x['counts'].get('TotalContactQueriesWithFeedback',x['counts']['ActualContacts']),str(x['counts']['PredictionHits'])+'/'+str(x['counts']['PredictionRequests'])] for x in a['full_runs'] if x['counts']])
  text+='Mediany w surowym result obejmują wywołania wraz z abstencją. Surowy p95 używa indeksu floor((n−1)×0,95); widok udanych decyzji używa nearest-rank. Pełne sekwencje odrzuconych alternatyw zapisano dopiero w końcowym audycie22,6s; wcześniejsze dzienniki mają ich rankingi i liczbę akcji, a nie każdą odrzuconą taśmę. Koszt prób wyboru obejmuje inicjalizację, zapis planów/dziennika i końcową odmowę; koszt zwróconych decyzji jest osobno. Replays niezależne, korekty, odrzucone eksperymenty i postprocessing są w `budget.json`; nie doliczano historycznego149 jako nowego. Liczniki są rzeczywiste, trafienia cache dokładnie kluczowane stanem/kolejką/modelem. Nie zapisano zegarów CPU osobno dla każdego K1/kontaktu/beam: czasów tych nie estymujemy z liczników. Profil pokazuje rzeczywiste sumy i rozkład wywołań; brak podziału czasu wewnątrz wywołania jest ograniczeniem pomiaru.\n\nNa dokładnym recoveryA 14,250CPU-s/15,463s nowego sterowania to około0,92 rdzenia, B około1,09. Naiwna suma czterech niezależnych zawodników to około3,7–4,4 rdzenia na te **lokalne odcinki**, z p95 rzędu0,5–0,6s przekraczającym okres decyzji0,2s. Nie uwzględnia interakcji ani gorszych stanów; pełny nowyA spędza10,625CPU-s na pierwszych0,4s. To nie jest gotowe na czterech zawodników w czasie rzeczywistym. Następny krok: causal recourse generująca różne polityki na następnym rzeczywistym stanie, dedykowane CPU timery per rola, a dopiero po pozytywnych bramkach nowy pełny bieg. Nie potrzeba dalszego strojenia mocy lub μ.\n\n![Zmierzony profil wywołań](figures/cpu.png)\n\n'
  text+='## 6. Jednoznaczne odpowiedzi\n\n1. Stary legalny plan traci legalność po zastąpieniu przewidywanego1s rzeczywistym1s przy identycznej kolejce i identycznych przyszłych komendach; długa otwarta trajektoria wzmacnia błąd modelu/integracji.\n2. Oba mechanizmy istnieją, ale odmowa odziedziczonej taśmy nie wymaga nowegoK1. Dyskretna zmiana K1 po5,8s i odmienna dostępność search przy22,6s są osobnymi przyczynami.\n3. Tak lokalnie: dokładny1s A/B odzyskano autonomicznym sprzężeniem i zakończono diagnostyczny odcinek legalnie. Nie dowodzi to trzech okrążeń.\n4. Częściowo: ostatni łukB po legalnym prefiksie jest krótszy/szybszy. Łuk2.2 bez poprawy, ręczny benchmark nieodnaleziony, pełny start nadal blokuje certyfikat odporności.\n5. B zatrzymuje inną legalną politykę i nie otwiera naprawy, którąA uruchamia; większa prędkość nie płaci za dodatkowe11–17m.\n6. Nie potwierdzono pełnej autonomicznej poprawy naA aniB. NowyA abstain0,4s, nowyB N/D. Wynik PARTIAL.\n7. Koszt dokładnie zapisano dla zakresów w tabeli; brak gotowości produkcyjnej i brak pełnego kosztu nowego biegu. Potrzebne jest pokrycie recourse i profilowanie ról przed skalowaniem do czterech.\n\n'
  text+='## 7. Odtwarzanie i walidacja\n\n`tools/robust-autonomous-racing/README.md` podaje jawne flagi; ponowne eksperymenty wymagają osobnego katalogu wyników/nowej nazwy, bo istniejące próby są chronione przed nadpisaniem. `analyze150.py <unikalna-etykieta>` i `report150.py <unikalna-etykieta>` przetwarzają tylko zapisane wyniki i księgują CPU. Pełna telemetria: native gzip plus CSV.gz; decyzje: hash-chain JSONL; polityki: `plans/`; kontrfakty: `diagnosis-safe/`; pełne rankingi22,6: `critical22-*.json.gz`. Provenance przechowuje SHA surowych wyników i kanoniczne SHA niezmienionej fizyki. Pośrednie wersje algorytmu są opisane SourceHashes w result i historią commitów; pilot rolling używał query h0, dalsze próbyh0,01. Niezależny audyt odtworzył właściwą wersję polityki każdej próby.\n\nReplay: [pełna próbaA](http://127.0.0.1:8018/tools/replay-viewer/?case=robust150&run=robust150-tube-full-A&t=0.4), [lokalne recoveryA](http://127.0.0.1:8018/tools/replay-viewer/?case=robust150&run=robust150-exact-recovery-A&t=1), [ostatni łukB po prefiksie](http://127.0.0.1:8018/tools/replay-viewer/?case=robust150&run=robust150-prefix-B-45&t=46). Domyślny nowy replay pokazuje odmowę pełnego startu. Brak wizualnej kontroli browsera: backend CUA nie inicjalizował sesji; widoki sprawdzono przez Node/HTTP, a wykresy jako PNG.\n\nWyniki testów i WindowsCI są osobno w `validation.json`; statusu nie wolno interpretować jako sportowego PASS. Fizykę, produkcyjne parametry i wyniki145–149 zachowano bez zmian.\n'
  (D/'REPORT.md').write_text(text,encoding='utf-8',newline='\n')
  print('figures and report saved')
def journal(name):
 rows=[json.loads(x)['Payload'] for x in (D/'native'/(name+'-decisions.jsonl')).read_text(encoding='utf-8').splitlines()]
 return [x for x in rows if x['Event']=='decision']
